(() => {
const data=window.catalogData, money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const groups={'Progresso':['Level máximo (2800)'],'Estilos de luta':['God Human','Sanguine Art'],'Espadas e armas':['Cursed Dual Katana','True Triple Katana','Shark Anchor','Soul Guitar'],'Raças':['Qualquer Raça V4','Humano V4','Coelho V4','Tubarão V4','Anjo V4','Vampiro V4','Robô V4','Dragão V4','Possui Raça V3'],'Frutas míticas':['Fruta mítica aleatória','Dragon','Kitsune']};
let query='',sort='',selected=new Set(),availability='all';
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function filtered(){let list=data.accounts.filter(p=>normalize(p.name+' '+p.features.join(' ')).includes(normalize(query))&&[...selected].every(f=>p.features.includes(f))&&availability!=='manual');if(sort)list.sort((a,b)=>sort==='asc'?a.price-b.price:b.price-a.price);return list}
const faq=(items)=>`<section class="sc-faq wrap faq"><h2>Perguntas frequentes</h2>${items.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}</summary><div class="faq-answer"><p>${a}</p></div></details>`).join('')}</section>`;
function gifts(){return `<div class="gc-page wrap"><span class="eyebrow">GIFT CARDS ROBLOX</span><h1>Escolha o valor do seu presente</h1><p class="sc-intro">Escolha o valor e adicione saldo à sua conta Roblox. Após a confirmação do pagamento, a entrega é automática.</p><div class="gc-grid">${[...data.gifts].sort((a,b)=>a.value-b.value).map(p=>`<article class="gc-card"><div class="gc-image"><img src="${p.image}" alt="${p.name}"></div><h2>Gift Card Roblox <span>R$ ${p.value}</span></h2><strong>${money(p.price)}</strong><button class="button" data-product="${p.id}">COMPRAR AGORA →</button></article>`).join('')}</div><div class="gc-benefits">${[['ϟ','Entrega Automática','Receba o código diretamente em seu painel após a confirmação do pagamento.'],['♢','100% Seguro','Cartões oficiais para resgate na plataforma Roblox.'],['↗','Resgate Fácil','Insira o código na página oficial do Roblox para resgatar o saldo.']].map(([icon,h,p])=>`<div><i>${icon}</i><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></div>${faq([['É seguro comprar?','Confira a procedência do cartão, a moeda e as condições de resgate. Esta recriação não processa pagamentos.'],['Quando recebo meu Gift Card?','No site original, o código é disponibilizado no painel após aprovação. Confira os detalhes do cartão antes de continuar.'],['Como resgatar meu saldo?','Acesse roblox.com/redeem, entre na sua conta Roblox e siga as instruções oficiais.']])}`}
function card(p){return `<article class="sc-account"><button class="sc-art" data-product="${p.id}" aria-label="Ver ${p.name}"><img src="${p.image}" alt="${p.name}" loading="lazy" data-fallback="/assets/adventure.svg"><span><b>ϟ</b> ENTREGA AUTOMÁTICA</span></button><div class="sc-card-copy"><button class="sc-title" data-product="${p.id}">${p.name}</button><ul>${p.features.map(f=>`<li>${f==='God Human'?'<img src="/assets/original/683978eeec9791c2.png" alt="">':f==='Cursed Dual Katana'?`<img src="${window.originalMedia.cdk}" alt="">`:f==='Kitsune'?`<img src="${window.originalMedia.products[9]}" alt="">`:f==='Fruta mítica aleatória'?'<i class="sc-mythic">?</i>':'<i class="sc-level"></i>'}<span>${f==='Fruta mítica aleatória'?'Fruta mítica <b>1× GARANTIDA</b>':f}</span></li>`).join('')}</ul><div class="sc-price"><strong>${money(p.price)}</strong>${p.old?`<del>${money(p.old)}</del>`:''}</div><button class="button" data-product="${p.id}">ESCOLHER CONTA</button><small class="sc-stock"><b>♧</b> Disponível agora · ${p.stock} ${p.stock===1?'conta':'contas'}</small><small class="sc-verified">♢ Conta verificada · entrega garantida</small></div></article>`}
const guide=[['conta-pronta','O que é uma conta Blox Fruits pronta?','É uma conta com progresso já avançado dentro do jogo. Confira os recursos descritos em cada anúncio.'],['o-que-vem','O que pode vir em uma conta?','Level, frutas, estilos de luta, espadas e outros recursos variam por conta.'],['escolher-conta','Como escolher a conta certa?','Use a busca e combine filtros. Todas as características selecionadas devem estar presentes.'],['pvp','Contas para PVP','Confira os recursos indicados para sua build, como God Human e Cursed Dual Katana.'],['level-frutas-raca','Level, frutas e raça','Compare nível, frutas e raça antes de escolher. Não presuma recursos que não estão descritos.'],['entrega-automatica','Entrega automática','No original, os dados ficam na área segura do pedido após aprovação. Esta versão não entrega credenciais.'],['conferir','O que conferir antes de comprar?','Confira produto, preço, disponibilidade, características e condições de entrega.']];
function runningStrip(){const offers=[['1.000 Robux',window.shopPricing.robux(1000)],['500 Robux',window.shopPricing.robux(500)],['5.000 Robux',window.shopPricing.robux(5000)],['1.500 Robux',window.shopPricing.robux(1500)],['2.000 Robux',window.shopPricing.robux(2000)],['Conta Blox Fruits',Math.min(...data.accounts.map(p=>p.price))],['Gift Card R$ 25',data.gifts.find(p=>p.value===25).price]];const chips=offers.map(([name,price])=>`<div class="ticker-item"><span class="sc-running-icon"><img src="/assets/original/570507b5e2ef9723.svg" alt=""></span><span>Na loja</span><b>${name}</b><small>A PARTIR DE ${money(price)}</small></div>`).join('');return `<div class="live sc-running-strip" aria-label="Opções da loja em movimento"><div class="ticker-viewport"><div class="ticker-track"><div class="ticker-group">${chips}</div><div class="ticker-group" aria-hidden="true">${chips}</div></div></div></div>`}

function accounts(){query='';sort='';selected.clear();availability='all';return `<section class="sc-hero" style="--sc-hero:url('${data.hero}')"><div class="wrap"><div class="breadcrumb"><a href="/">⌂ Início</a> › <a href="/contas">Contas</a> › Blox Fruits</div><h1>Contas <em>Blox Fruits</em> prontas<br>para jogar</h1><p>Escolha os recursos que deseja e encontre a conta ideal.</p></div></section>${runningStrip()}<section class="wrap sc-catalog" id="contas-disponiveis"><h2>Encontre sua conta</h2><p>Use a busca ou selecione recursos para ver apenas as contas que combinam com você.</p><div class="sc-toolbar"><button data-sc-filter aria-haspopup="dialog">☷ FILTRAR <span id="sc-filter-count"></span></button><select id="sc-sort" aria-label="Ordenar contas"><option value="">Ordenar</option><option value="asc">Menor preço</option><option value="desc">Maior preço</option></select><label>⌕ <input type="search" id="sc-search" aria-label="Buscar contas Blox Fruits" placeholder="Buscar conta, level, fruta, raça ou item..."></label></div><div id="sc-active"></div><p id="sc-count" role="status">7 contas encontradas</p><div id="sc-results" class="sc-grid">${data.accounts.map(card).join('')}</div></section>${faq([['É seguro comprar?','Confira as características, a procedência e as condições de suporte antes de escolher sua conta.'],['Quando recebo minha conta?','O original informa entrega em 24h a 48h úteis após confirmação, podendo chegar antes. Esta versão não realiza entregas.'],['Como funciona o suporte?','A loja original atende pelo Discord e pelo chat do pedido.']])}<section class="wrap sc-guide"><span class="eyebrow">GUIA BLOX FRUITS</span><h2>Guia rápido sobre contas Blox Fruits</h2><p>Entenda como escolher uma conta pronta e o que conferir antes de comprar.</p><div class="guide"><aside><b>NESTE GUIA</b>${guide.map(([id,h])=>`<a href="#${id}">${h}</a>`).join('')}</aside><div>${guide.map(([id,h,p])=>`<article id="${id}"><h3>${h}</h3><p>${p}</p></article>`).join('')}<a href="#contas-disponiveis" class="button">VER PRODUTOS ↑</a></div></div></section><dialog id="sc-filters" aria-labelledby="sc-filter-title"><div class="sc-filter-head"><h2 id="sc-filter-title">Filtros</h2><button data-sc-close aria-label="Fechar filtros">×</button></div><p>As contas devem ter todos os recursos selecionados.</p>${Object.entries(groups).map(([h,items])=>`<fieldset><legend>${h}</legend>${items.map(f=>`<label><input type="checkbox" data-sc-feature value="${f}">${f}</label>`).join('')}</fieldset>`).join('')}<fieldset><legend>Disponibilidade</legend>${[['all','Todas as contas'],['stock','Em estoque'],['auto','Entrega automática'],['manual','Entrega manual']].map(([value,h])=>`<label><input type="radio" name="sc-availability" value="${value}" ${value==='all'?'checked':''}>${h}</label>`).join('')}</fieldset><div class="sc-filter-actions"><button data-sc-clear>Limpar</button><button class="button" data-sc-close id="sc-apply">Ver 7 contas</button></div></dialog>`}
function refresh(){if(!document.querySelector('#sc-results'))return;const list=filtered();document.querySelector('#sc-results').innerHTML=list.length?list.map(card).join(''):'<div class="sc-empty"><h3>Nenhuma conta encontrada</h3><p>Tente outra busca ou remova alguns filtros.</p><button class="button" data-sc-clear>Limpar filtros e busca</button></div>';document.querySelector('#sc-count').textContent=list.length+' '+(list.length===1?'conta encontrada':'contas encontradas');document.querySelector('#sc-filter-count').textContent=selected.size?'('+selected.size+')':'';document.querySelector('#sc-active').innerHTML=[...selected].map(f=>`<span>${f}</span>`).join('');if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll('#sc-results .sc-account').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:260,delay:Math.min(i*35,105),easing:'cubic-bezier(.22,1,.36,1)',fill:'backwards'}));const apply=document.querySelector('#sc-apply');if(apply)apply.textContent='Ver '+list.length+(list.length===1?' conta':' contas');}
document.addEventListener('input',e=>{if(e.target.id==='sc-search'){query=e.target.value;refresh()}});
document.addEventListener('change',e=>{if(e.target.id==='sc-sort'){sort=e.target.value;refresh()}if(e.target.matches('[data-sc-feature]')){e.target.checked?selected.add(e.target.value):selected.delete(e.target.value);refresh()}if(e.target.name==='sc-availability'){availability=e.target.value;refresh()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const dialog=document.querySelector('#sc-filters');if(b.hasAttribute('data-sc-filter'))dialog?.showModal();if(b.hasAttribute('data-sc-close'))dialog?.close();if(b.hasAttribute('data-sc-clear')){selected.clear();query='';availability='all';document.querySelector('#sc-search').value='';dialog?.querySelectorAll('input[type=checkbox]').forEach(c=>c.checked=false);const radio=dialog?.querySelector('input[value=all]');if(radio)radio.checked=true;refresh()}});
window.specialCatalog={gifts,accounts,filtered,data};
})();



